          },
          {
            "weekday": {
              "type": "string",
              "description": "第三天天气预报的日期标签。",
              "sampleValue": "后天"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "第三天适合直接显示的温度范围。",
              "sampleValue": "25-32°"
            },
            "rainProbabilityPercent": {
              "type": "string",
              "description": "第三天白天降雨概率百分比。",
              "sampleValue": "雨20%"
            },
            "coldLevel": {
              "type": "string",
              "description": "第三天感冒指数展示文本。",
              "sampleValue": "感冒低"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/rain.png",
      "description": "天气库雨天彩色图标，适合表达下雨预报和降雨概率。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "天气库多云彩色图标，适合表达云量较多的天气预报。"
    },
    {
      "src": "resources/base/media/sunny.png",
      "description": "天气库晴天彩色图标，适合表达晴朗天气预报。"
    }
  ]
}

